discovery.code:
// page on https://app.example.com
await fetch("https://api.example.com/orders", {
  method: "POST",
  headers: { "Content-Type": "application/json" },
  credentials: "include",
  body: JSON.stringify({ id: 42 })
});

// the API answers every request with:
//   Access-Control-Allow-Origin: *

